-- Isolated identities; run inside BEGIN / ROLLBACK.
do $$
declare u uuid:=gen_random_uuid(); st uuid:=gen_random_uuid(); sh uuid; c uuid; c2 uuid; pet uuid:=gen_random_uuid(); staff uuid:=gen_random_uuid(); svc uuid:=gen_random_uuid(); svc2 uuid:=gen_random_uuid(); b jsonb; n int; rejected boolean; tpl uuid:=gen_random_uuid(); pkg uuid:=gen_random_uuid(); d date:=current_date+1;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(u,'qa.details.'||u||'@example.com','{"role":"barber","segment":"pet","shop_name":"QA Details"}'),(st,'qa.details.staff.'||st||'@example.com','{}');
 select id into sh from public.shops where owner_user_id=u;
 perform set_config('request.jwt.claim.role','service_role',true);
 insert into public.barbers(id,shop_id,user_id,name) values(staff,sh,st,'QA Details staff');
 insert into public.barber_schedule(barber_id,day_of_week,is_active,start_time,end_time) select staff,day,true,'09:00','18:00' from generate_series(0,6) day;
 insert into public.services(id,shop_id,name,price,duration_minutes) values(svc,sh,'QA Details bath',50,30),(svc2,sh,'QA No taxi',10,15);
 insert into public.service_pet_transport(service_id,shop_id,enabled,fee,pricing_mode) values(svc,sh,true,12.50,'fixed');
 perform set_config('request.jwt.claim.role','authenticated',true);
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 c:=(public.quick_register_customer(sh,'(19) 99999-1234')->>'id')::uuid;
 if (select name from public.shop_customers where id=c)<>'' then raise exception 'FAIL invented customer name'; end if;
 if (public.quick_register_customer(sh,'+55 19 99999-1234')->>'id')::uuid<>c then raise exception 'FAIL duplicate phone contact'; end if;
 if (select count(*) from public.shop_customers where shop_id=sh)<>1 then raise exception 'FAIL duplicate contact persisted'; end if;
 perform public.upsert_pet_customer(sh,'19999991234','Tutor completado');
 if (public.quick_register_customer(sh,'19999991234')->>'name')<>'Tutor completado' then raise exception 'FAIL existing name overwritten'; end if;
 c2:=(public.quick_register_customer(sh,'19999991235')->>'id')::uuid;
 insert into public.pets(id,shop_id,customer_id,name) values(pet,sh,c2,'QA Pet');
 b:=public.create_operational_booking_with_details(sh,staff,c2,pet,d,'10:00',array[svc],'  Alergia a perfume  ',true,'Rua de teste, 123','Portão azul',null);
 if (b->>'quoted_amount')::numeric<>62.50 or (b->>'pet_transport_fee')::numeric<>12.50 or b->>'notes'<>'Alergia a perfume' or b->>'pet_transport_notes'<>'Portão azul' then raise exception 'FAIL details or fixed taxi total'; end if;
 if b->>'client_name'<>'19999991235' then raise exception 'FAIL unnamed contact not identifiable in booking'; end if;
 perform public.update_booking_status((b->>'id')::uuid,'in_progress');
 perform public.complete_booking((b->>'id')::uuid,array[svc],'pix',62.50,null);
 if (select amount from public.financial_transactions where booking_id=(b->>'id')::uuid)<>62.50 then raise exception 'FAIL transport not included in cash flow'; end if;
 select count(*) into n from public.bookings where shop_id=sh;
 rejected:=false; begin perform public.create_operational_booking_with_details(sh,staff,c2,pet,d,'11:00',array[svc],null,true,'x',null,null); exception when others then rejected:=true; end;
 if not rejected or (select count(*) from public.bookings where shop_id=sh)<>n then raise exception 'FAIL invalid address created partial booking'; end if;
 rejected:=false; begin perform public.create_operational_booking_with_details(sh,staff,c2,pet,d,'11:00',array[svc],null,true,'Rua de teste, 123',null,-1); exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL negative taxi fee'; end if;
 rejected:=false; begin perform public.create_operational_booking_with_details(sh,staff,c2,pet,d,'11:00',array[svc2],null,true,'Rua de teste, 123',null,null); exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL taxi unavailable for selected services'; end if;
 rejected:=false; begin perform public.quick_register_customer(sh,'12'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL invalid phone accepted'; end if;
 execute 'reset role';
 update public.service_pet_transport set pricing_mode='quote',fee=0 where service_id=svc;
 insert into public.service_packages(id,shop_id,name,total_sessions,price,active) values(tpl,sh,'QA Details package',4,200,true);
 insert into public.customer_packages(id,shop_id,package_id,customer_id,pet_id,total_sessions,used_sessions,status) values(pkg,sh,tpl,c2,pet,4,0,'active');
 perform set_config('request.jwt.claim.sub',st::text,true);
 perform set_config('request.jwt.claims',json_build_object('sub',st,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if (public.quick_register_customer(sh,'19999991235')->>'id')::uuid<>c2 then raise exception 'FAIL staff quick registration'; end if;
 c:=(public.quick_register_customer(sh,'19999991236')->>'id')::uuid;
 insert into public.pets(shop_id,customer_id,name) values(sh,c,'QA pet criado pela equipe');
 b:=public.create_operational_booking_with_details(sh,staff,c2,pet,d,'12:00',array[svc],'Sem perfume',true,'Rua do teste, 1',null,null);
 if (b->>'pet_transport_fee')::numeric<>0 or (b->>'quoted_amount')::numeric<>50 then raise exception 'FAIL pending taxi quote'; end if;
 perform public.set_pet_transport_fee((b->>'id')::uuid,15);
 perform public.set_pet_transport_fee((b->>'id')::uuid,15);
 if (select quoted_amount from public.bookings where id=(b->>'id')::uuid)<>65 then raise exception 'FAIL taxi fee counted twice'; end if;
 perform public.complete_booking((b->>'id')::uuid,array[svc],'pix',15,pkg);
 if (select amount from public.financial_transactions where booking_id=(b->>'id')::uuid)<>15 then raise exception 'FAIL package must cover only services'; end if;
 if (select used_sessions from public.customer_packages where id=pkg)<>1 then raise exception 'FAIL package usage'; end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 rejected:=false; begin perform public.quick_register_customer(sh,'19999991236'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL cross-tenant quick customer'; end if;
 rejected:=false; begin perform public.create_operational_booking_with_details(sh,staff,c2,pet,d,'13:00',array[svc]); exception when others then rejected:=true; end;
 if not rejected then raise exception 'FAIL cross-tenant booking details'; end if;
 execute 'reset role';
 if has_function_privilege('anon','public.quick_register_customer(uuid,text)','EXECUTE') or has_function_privilege('anon','public.create_operational_booking_with_details(uuid,uuid,uuid,uuid,date,time,uuid[],text,boolean,text,text,numeric)','EXECUTE') then raise exception 'FAIL internal RPC exposed to anonymous users'; end if;
end; $$;
